        /// <summary>
        /// Core implementation hook for verifying create permissions on <paramref name="toCreate"/>.
        /// </summary>
        /// <param name="userContext">The contextual user information and assigned roles.</param>
        /// <param name="toCreate">The entity to create.</param>
        /// <returns>An awaitable <see cref="Task{ErrorOr}"/> indicating whether creation is permitted.</returns>
        protected override async Task<ErrorOr<Success>> IsAllowedToCreateImplementation(IUserContext userContext, IPackage toCreate)
        {
            if (!userContext.IsAuthenticated || !userContext.AccountId.HasValue)
            {
                return Error.Unauthorized(description: "Unauthenticated user cannot create a package.");
            }

            if (toCreate.Owner == userContext.AccountId.Value)
            {
                return PermissionGuard.GuardPermission(userContext, PermissionKind.PublishPackageToPersonalScope);
            }

            if (PermissionGuard.HasPermission(userContext, PermissionKind.ManageOrganizations))
            {
                return Result.Success;
            }

            var orgGuard = PermissionGuard.GuardPermission(userContext, PermissionKind.PublishPackageToOrganizationScope);

            if (orgGuard.IsError)
            {
                return orgGuard;
            }

            var orgResult = await this.organizationService.ReadAsync(userContext, CancellationToken.None, [toCreate.Owner]);

            if (orgResult.IsError || orgResult.Value.Count == 0)
            {
                return Error.Forbidden(description: "Access denied: target organization was not found or is not accessible.");
            }

            var organization = orgResult.Value[0];

            if (!organization.Member.Contains(userContext.AccountId.Value) && !organization.Administrator.Contains(userContext.AccountId.Value))
            {
                return Error.Forbidden(description: "Access denied: user is not a member of the target organization.");
            }

            return Result.Success;
